93	import { flatten, isServer, watchOnlineStatus } from '@salesforce/retail-react-app/app/utils/utils';
94	
95	import Seo from '@salesforce/retail-react-app/app/components/seo';
96	import ShopperAgent from '@salesforce/retail-react-app/app/components/shopper-agent';
97	import { initializeRegistry } from '@salesforce/retail-react-app/app/page-designer/registry';
98	
99	// Initialize registry synchronously at module load time so components are available during SSR
100	initializeRegistry();
101	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
102	import { getPathWithLocale } from '@salesforce/retail-react-app/app/utils/url';
103	import { useShopperAgent } from '@salesforce/retail-react-app/app/hooks/use-shopper-agent';
104	
105	type AppProps = {
106	  children: React.ReactNode;
107	};
108	
109	type CategoryNode = {
110	  id: string;
111	  categories?: Record<string, CategoryNode>;
112	  [key: string]: unknown;
113	};
114	
115	const PlaceholderComponent = (): React.ReactElement => (
116	  <Center p="2">
117	    <Spinner size="lg" />
118	  </Center>
119	);
120	
121	const DrawerMenuItemWithData = withCommerceSdkReact(
122	  // any: withCommerceSdkReact's injected item-component props aren't typed upstream;
123	  // narrowing here would require re-deriving withCommerceSdkReact's own generic shape,
124	  // out of scope for a copy-first port.
125	  ({ itemComponent: ItemComponent, data, ...rest }: any) => (
126	    <Fade in={true}>
127	      <ItemComponent {...rest} item={data} itemComponent={DrawerMenuItemWithData} />
128	    </Fade>
129	  ),
130	  {
131	    hook: useCategory,
132	    queryOptions: ({ item }: { item: { id: string } }) => ({
133	      parameters: {
134	        id: item.id,
135	      },
136	    }),
137	    placeholder: PlaceholderComponent,
138	  },
139	);
140	
141	const ListMenuContentWithData = withCommerceSdkReact(
142	  // any: same as DrawerMenuItemWithData above.
143	  ({ data, ...rest }: any) => (
144	    <Fade in={true}>
145	      <ListMenuContent {...rest} item={data} />
146	    </Fade>
147	  ),
148	  {
149	    hook: useCategory,
150	    queryOptions: ({ item }: { item: { id: string } }) => ({
151	      parameters: {
152	        id: item.id,
153	        levels: 2,
154	      },
155	    }),
156	    placeholder: PlaceholderComponent,
157	  },
158	);
159	
160	const App = ({ children }: AppProps): React.ReactElement => {
161	  const { data: categoriesTree } = useCategory({
162	    parameters: { id: CAT_MENU_DEFAULT_ROOT_CATEGORY, levels: CAT_MENU_DEFAULT_NAV_SSR_DEPTH },
163	  });
164	  const categories = flatten((categoriesTree || {}) as CategoryNode, 'categories');
165	  const { getTokenWhenReady } = useAccessToken();
166	  const { usid } = useUsid();
167	  const appOrigin = useAppOrigin();
168	  const activeData = useActiveData();
169	  const history = useHistory();
170	  const location = useLocation();
171	  const authModal = useAuthModal();
172	  const { site, locale, buildUrl } = useMultiSite();
173	  const {
174	    isOpen: isStoreLocatorOpen,
175	    onOpen: onOpenStoreLocator,
176	    onClose: onCloseStoreLocator,
177	  } = useStoreLocatorModal();
178	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
179	  const { req } = useServerContext();
180	
181	  const [isOnline, setIsOnline] = useState(true);
182	  const styles = useStyleConfig('App');
183	  const { isOpen, onOpen, onClose } = useDisclosure();
184	
185	  // Determine Page Designer mode from URL - use req for server-side detection
186	  const pageDesignerMode = useMemo(() => {
187	    const queryParams = location?.search || '';
188	    if (queryParams.includes('mode=EDIT')) return 'EDIT';
189	    else if (queryParams.includes('mode=PREVIEW')) return 'PREVIEW';
190	    return undefined;
191	    // matches upstream base _app exactly.
192	  }, [req?.url]);
193	
194	  const targetLocale = getTargetLocale({
195	    getUserPreferredLocales: () => {
196	      // CONFIG: This function should return an array of preferred locales. They can be
197	      // derived from various sources. Below are some examples of those:
198	      //
199	      // - client side: window.navigator.languages
200	      // - the page URL they're on (example.com/en-GB/home)
201	      // - cookie (if their previous preference is saved there)
202	      //
203	      // If this function returns an empty array (e.g. there isn't locale in the page url),
204	      // then the app would use the default locale as the fallback.
205	
206	      // NOTE: Your implementation may differ, this is just what we did.
207	      return [locale?.id || DEFAULT_LOCALE];
208	    },
209	    l10nConfig: site.l10n,
210	  });
211	
212	  // If the translation file exists, it'll be served directly from static folder (and won't reach this code here).
213	  // However, if the file is missing, the App would render a 404 page.
214	  const is404ForMissingTranslationFile = /\/static\/translations\/compiled\/[^.]+\.json$/.test(location?.pathname);
215	
216	  // Fetch the translation message data using the target locale.
217	  const { data: messages } = useQuery({
218	    queryKey: ['app', 'translations', 'messages', targetLocale],
219	    queryFn: () => {
220	      if (is404ForMissingTranslationFile) {
221	        // Return early to prevent an infinite loop
222	        // Otherwise, it'll continue to fetch the missing translation file again
223	        return {};
224	      }
225	      return fetchTranslations(targetLocale, appOrigin);
226	    },
227	    enabled: isServer,
228	  });
229	
230	  // Used to conditionally render header/footer for checkout page
231	  const isCheckout = /\/checkout$/.test(location?.pathname);
232	
233	  const { l10n } = site;
234	  // Get the current currency to be used through out the app
235	  const currency = locale.preferredCurrency || l10n.defaultCurrency;
236	
237	  // Handle creating a new basket if there isn't one already assigned to the current
238	  // customer.
239	  const { data: customer } = useCurrentCustomer();
240	  const { data: basket, dataUpdatedAt: basketQueryLastUpdateTime } = useCurrentBasket();
241	  const config = getConfig();
242	
243	  const updateBasket = useShopperBasketsMutation('updateBasket');
244	  const updateCustomerForBasket = useShopperBasketsMutation('updateCustomerForBasket');
245	
246	  useEffect(() => {
247	    // update the basket currency if it doesn't match the current locale currency
248	    if (basket?.currency && basket?.currency !== currency) {
249	      updateBasket.mutate({
250	        parameters: { basketId: basket.basketId },
251	        body: { currency },
252	      });
253	    }
254	    // matches upstream base _app exactly.
255	  }, [basket?.currency]);
256	
257	  const commerceAgentConfiguration = useMemo(() => {
258	    return getCommerceAgentConfig();
259	    // matches upstream base _app exactly.
260	  }, [config.app.commerceAgent]);
261	
262	  useEffect(() => {
263	    // update the basket customer email
264	    if (basket && customer?.isRegistered && customer?.email && customer?.email !== basket?.customerInfo?.email) {
265	      updateCustomerForBasket.mutate({
266	        parameters: { basketId: basket.basketId },
267	        body: {
268	          email: customer.email,
269	        },
270	      });
271	    }
272	    // matches upstream base _app exactly.
273	  }, [customer?.isRegistered, customer?.email, basket?.customerInfo?.email]);
274	
275	  useEffect(() => {
276	    // Listen for online status changes.
277	    watchOnlineStatus((online: boolean) => {
278	      setIsOnline(online);
279	    });
280	  }, []);
281	
282	  // Handle updating the shopper context
283	  useUpdateShopperContext();
284	
285	  useEffect(() => {
286	    // Lets automatically close the mobile navigation when the
287	    // location path is changed.
288	    onClose();
289	    // matches upstream base _app exactly.
290	  }, [location]);
291	
292	  // SFCC-885: the mobile drawer's isOpen state above is otherwise only ever closed by route
293	  // changes (the effect above) or an explicit close control — nothing closes it on a resize or
294	  // orientation change. That's a real gap, not a hardening: DrawerMenu renders a Chakra
295	  // <Drawer>, which always portals its content straight to document.body, so HideOnDesktop's
296	  // display:none on its wrapper (below) never actually hides an already-open drawer once the
297	  // viewport crosses into desktop width — the drawer keeps rendering full-screen on top of the
298	  // now-visible desktop nav. Closing it here whenever the viewport is no longer mobile (same
299	  // MOBILE_DESKTOP_SPLIT the HideOnDesktop/HideOnMobile split below already uses) fixes that for
300	  // every way the crossing can happen, not just a device rotation.
301	  const isMobileViewport = useBreakpointValue({ base: true, [MOBILE_DESKTOP_SPLIT]: false });
302	  useEffect(() => {
303	    if (isMobileViewport === false) onClose();
304	  }, [isMobileViewport]);
305	
306	  const onLogoClick = (): void => {
307	    // Goto the home page.
308	    const path = buildUrl(HOME_HREF);
309	
310	    history.push(path);
311	
312	    // Close the drawer.
313	    onClose();
314	  };
315	
316	  const onCartClick = (): void => {
317	    const path = buildUrl('/cart');
318	    history.push(path);
319	
320	    // Close the drawer.
321	    onClose();
322	  };
323	
324	  const onAccountClick = (): void => {
325	    // Link to account page if registered; Header component will show auth modal for guest users
326	    const path = buildUrl('/account');
327	    history.push(path);
328	  };
329	
330	  const onWishlistClick = (): void => {
331	    // Link to wishlist page if registered; Header component will show auth modal for guest users
332	    const path = buildUrl('/account/wishlist');
333	    history.push(path);
334	  };
335	
336	  const { actions: shopperAgentActions } = useShopperAgent();
337	
338	  const trackPage = (): void => {
339	    activeData.trackPage(site.id, locale.id, currency);
340	  };
341	
342	  useEffect(() => {
343	    trackPage();
344	    // matches upstream base _app exactly.
345	  }, [location]);
346	
347	  const getHrefForLocale = (localeId: string): string =>
348	    `${appOrigin}${getRouterBasePath()}${getPathWithLocale(localeId, buildUrl, {
349	      location: { ...location, search: '' },
350	    })}`;
351	
352	  return (
353	    <Box className="sf-app" {...styles.container}>
354	      <StorefrontPreview getToken={getTokenWhenReady} getBasePath={getRouterBasePath}>
355	        <IntlProvider
356	          onError={(err) => {
357	            if (!messages) {
358	              // During the ssr prepass phase the messages object has not loaded, so we can suppress
359	              // errors during this time.
360	              return;
361	            }
362	            if (err.code === 'MISSING_TRANSLATION') {
363	              // NOTE: Remove the console error for missing translations during development,
364	              // as we knew translations would be added later.
365	              logger.warn('Missing translation', {
366	                namespace: 'App.IntlProvider',
367	                additionalProperties: {
368	                  errorMessage: err.message,
369	                },
370	              });
371	              return;
372	            }
373	            throw err;
374	          }}
375	          locale={targetLocale}
376	          messages={messages}
377	          // For react-intl, the _default locale_ refers to the locale that the inline `defaultMessage`s are written for.
378	          // NOTE: if you update this value, please also update the following npm scripts in `template-retail-react-app/package.json`:
379	          // - "extract-default-translations"
380	          // - "compile-translations:pseudo"
381	          defaultLocale={DEFAULT_LOCALE}
382	        >
383	          <CurrencyProvider currency={currency}>
384	            <Seo>
385	              <meta name="theme-color" content={THEME_COLOR} />
386	              <meta name="apple-mobile-web-app-title" content={DEFAULT_SITE_TITLE} />
387	              <link rel="apple-touch-icon" href={getAssetUrl('static/img/global/apple-touch-icon.png')} />
388	              <link rel="manifest" href={getAssetUrl('static/manifest.json')} />
389	
390	              {/* Urls for all localized versions of this page (including current page)
391	              For more details on hrefLang, see https://developers.google.com/search/docs/advanced/crawling/localized-versions */}
392	              {site.l10n?.supportedLocales.map((l: { id: string }) => (
393	                <link rel="alternate" hrefLang={l.id.toLowerCase()} href={getHrefForLocale(l.id)} key={l.id} />
394	              ))}
395	              {/* A general locale as fallback. For example: "en" if default locale is "en-GB" */}
396	              <link rel="alternate" hrefLang={site.l10n.defaultLocale.slice(0, 2)} href={getHrefForLocale(locale.id)} />
397	              {/* A wider fallback for user locales that the app does not support */}
398	              <link rel="alternate" hrefLang="x-default" href={`${appOrigin}/`} />
399	            </Seo>
400	
401	            {commerceAgentConfiguration?.enabled === 'true' && (
402	              <ShopperAgent
403	                commerceAgentConfiguration={commerceAgentConfiguration}
404	                basketDoneLoading={basketQueryLastUpdateTime > 0}
405	              />
406	            )}
407	
408	            <ScrollToTop />
409	
410	            <Box id="app" display="flex" flexDirection="column" flex={1}>
411	              <SkipNavLink zIndex="skipLink">Skip to Content</SkipNavLink>
412	              {storeLocatorEnabled && <StoreLocatorModal isOpen={isStoreLocatorOpen} onClose={onCloseStoreLocator} />}
413	              <Island hydrateOn={'visible'}>
414	                <Box {...styles.headerWrapper}>
415	                  {!isCheckout ? (
416	                    <>
417	                      <AboveHeader />
418	                      <Header
419	                        onMenuClick={onOpen}
420	                        onLogoClick={onLogoClick}
421	                        onMyCartClick={onCartClick}
422	                        onMyAccountClick={onAccountClick}
423	                        onWishlistClick={onWishlistClick}
424	                        onStoreLocatorClick={onOpenStoreLocator}
425	                        onAgentClick={shopperAgentActions.open}
426	                      >
427	                        <HideOnDesktop>
428	                          <DrawerMenu
429	                            isOpen={isOpen}
430	                            onClose={onClose}
431	                            onLogoClick={onLogoClick}
432	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
433	                            itemsKey="categories"
434	                            itemsCountKey="onlineSubCategoriesCount"
435	                            itemComponent={DrawerMenuItemWithData}
436	                          />
437	                        </HideOnDesktop>
438	
439	                        <HideOnMobile>
440	                          <ListMenu
441	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
442	                            itemsKey="categories"
443	                            itemsCountKey="onlineSubCategoriesCount"
444	                            contentComponent={ListMenuContentWithData}
445	                          />
446	                        </HideOnMobile>
447	                      </Header>
448	                    </>
449	                  ) : (
450	                    <CheckoutHeader />
451	                  )}
452	                </Box>
453	              </Island>
454	              {!isOnline && <OfflineBanner />}
455	              <AddToCartModalProvider>
456	                <BonusProductSelectionModalProvider>
457	                  <SkipNavContent
458	                    style={{
459	                      display: 'flex',
460	                      flexDirection: 'column',
461	                      flex: 1,
462	                      outline: 0,
463	                    }}
464	                  >
465	                    <Box as="main" id="app-main" role="main" display="flex" flexDirection="column" flex="1">
466	                      <OfflineBoundary isOnline={false}>
467	                        <PageDesignerProvider
468	                          clientId="pwa-kit-client"
469	                          targetOrigin="*"
470	                          usid={usid ?? undefined}
471	                          mode={pageDesignerMode}
472	                        >
473	                          <PageDesignerInit />
474	                          {children}
475	                        </PageDesignerProvider>
476	                      </OfflineBoundary>
477	                    </Box>
478	                  </SkipNavContent>
479	
480	                  <Island hydrateOn={'visible'}>{!isCheckout ? <Footer /> : <CheckoutFooter />}</Island>
481	
482	                  <AuthModal {...authModal} />
483	                </BonusProductSelectionModalProvider>
484	              </AddToCartModalProvider>
485	            </Box>
486	          </CurrencyProvider>
487	        </IntlProvider>
488	      </StorefrontPreview>
489	    </Box>
490	  );
491	};
492	
493	export default App;
