  useShopperAgent: () => ({ actions: { open: vi.fn() } }),
}));
// Controllable stand-in for the real breakpoint match — SFCC-885's suite flips this between
// renders to simulate a resize/rotation crossing the mobile/desktop split. `undefined` mirrors
// useBreakpointValue's real pre-hydration/SSR return value (see index.tsx's own effect guard).
let mockIsMobileViewport: boolean | undefined = true;
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return { ...actual, useBreakpointValue: () => mockIsMobileViewport };
});

import App from '.';

describe('App (SFCC-863 — placeholder DNT modal removed)', () => {
  test('never renders DntNotification', () => {
    render(
      <App>
        <div>page content</div>
      </App>,
    );

    expect(DntNotification).not.toHaveBeenCalled();
    expect(screen.queryByTestId('dnt-notification-placeholder')).not.toBeInTheDocument();
  });

  test('the sibling AuthModal still renders, confirming the removal was surgical', () => {
    render(
      <App>
        <div>page content</div>
      </App>,
    );

    expect(screen.getByTestId('auth-modal-stub')).toBeInTheDocument();
  });
});

describe('App (SFCC-885 — mobile drawer closes when the viewport is no longer mobile)', () => {
  beforeEach(() => {
    mockIsMobileViewport = true;
    capturedOnMenuClick = undefined;
    drawerMenuSpy.mockClear();
  });

  test('closes an open drawer when a resize/rotation crosses into desktop width', () => {
    const { rerender } = render(
      <App>
        <div>page content</div>
      </App>,
    );

    act(() => capturedOnMenuClick?.());
    expect(drawerMenuSpy).toHaveBeenLastCalledWith(expect.objectContaining({ isOpen: true }));

    // Simulate the viewport crossing the mobile/desktop breakpoint (e.g. rotating to landscape).
    mockIsMobileViewport = false;
    rerender(
      <App>
        <div>page content</div>
      </App>,
    );

    expect(drawerMenuSpy).toHaveBeenLastCalledWith(expect.objectContaining({ isOpen: false }));
  });

  test('does not affect an already-closed drawer when the viewport is desktop-sized', () => {
    mockIsMobileViewport = false;
    render(
      <App>
        <div>page content</div>
      </App>,
    );

    expect(drawerMenuSpy).toHaveBeenLastCalledWith(expect.objectContaining({ isOpen: false }));
  });

  test('does not close the drawer while useBreakpointValue has not resolved yet (SSR/pre-hydration)', () => {
    mockIsMobileViewport = undefined;
    const { rerender } = render(
      <App>
        <div>page content</div>
      </App>,
    );

    act(() => capturedOnMenuClick?.());
    rerender(
      <App>
        <div>page content</div>
      </App>,
    );

    expect(drawerMenuSpy).toHaveBeenLastCalledWith(expect.objectContaining({ isOpen: true }));
  });

  test('stays open across a resize that remains within mobile widths', () => {
    const { rerender } = render(
      <App>
        <div>page content</div>
      </App>,
    );

    act(() => capturedOnMenuClick?.());
    // Still mobile (e.g. portrait -> a narrower/wider mobile size, not crossing the split).
    mockIsMobileViewport = true;
    rerender(
      <App>
        <div>page content</div>
      </App>,
    );

    expect(drawerMenuSpy).toHaveBeenLastCalledWith(expect.objectContaining({ isOpen: true }));
  });
});

