import React from 'react';
import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';
import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';

export type ZimmWishlistAuthDrawerProps = {
  /**
   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
   * flows — those trigger a full browser redirect; the user lands back already logged in.
   */
  onAuthSuccess?: () => void;
  /** Identifies this mounted instance so a social-IDP round-trip resumes the right
   *  `onAuthSuccess` — required because more than one instance (e.g. header + PDP) can be
   *  mounted on the page the shopper returns to. Stable per call site, e.g. `'header-wishlist'`
   *  or `'pdp-wishlist'` — see `useWishlistAuthDrawer`'s own doc comment. */
  intentId: string;
  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
   *  auth-gate handler — call the original action via onAuthSuccess instead. */
  children: React.ReactElement;
};

/**
 * Organism — wraps a single trigger element and gates its action behind auth.
 * If the customer is already registered the original onClick fires immediately.
 * If not, the Zimmermann auth drawer opens instead (passwordless email + optional social IDPs).
 *
 * Drop-in replacement for `withRegistration(Button)` on wishlist-specific entry points.
 * All SDK and auth logic lives in `useWishlistAuthDrawer` — this component is purely presentational.
 */
export const ZimmWishlistAuthDrawer = ({ onAuthSuccess, intentId, children }: ZimmWishlistAuthDrawerProps) => {
  const {
    isOpen,
    handleDrawerClose,
    handleTriggerClick,
    triggerRef,
    drawerTitle,
    description,
    emailValue,
    onEmailChange,
    onSendCode,
    onSignInWithApple,
    onSignInWithGoogle,
    isSocialEnabled,
    isPasswordlessEnabled,
    emailInputRef,
    onCreateAccount,
    isOtpAuthOpen,
    onOtpAuthClose,
    form,
    handlePasswordlessLogin,
    handleOtpVerification,
    registerModal,
  } = useWishlistAuthDrawer({ onAuthSuccess, intentId });

  return (
    <>
      {React.cloneElement(React.Children.only(children), { onClick: handleTriggerClick })}
      <ZimmDrawer
        isOpen={isOpen}
        onClose={handleDrawerClose}
        size="small"
        title={drawerTitle}
        finalFocusRef={triggerRef}
        initialFocusRef={emailInputRef}
      >
        <ErrorFallback>
          <ZimmAuthDrawerContent
            description={description}
            emailValue={emailValue}
            onEmailChange={onEmailChange}
            onSendCode={onSendCode}
            onSignInWithApple={onSignInWithApple}
            onSignInWithGoogle={onSignInWithGoogle}
            onCreateAccount={onCreateAccount}
            socialEnabled={isSocialEnabled}
            passwordlessEnabled={isPasswordlessEnabled}
            initialFocusRef={emailInputRef}
          />
        </ErrorFallback>
      </ZimmDrawer>
      <AuthModal {...registerModal} />
      <OtpAuth
        isOpen={isOtpAuthOpen}
        onClose={onOtpAuthClose}
        form={form}
        handleSendEmailOtp={handlePasswordlessLogin}
        handleOtpVerification={handleOtpVerification}
        hideCheckoutAsGuestButton={true}
      />
    </>
  );
};

import { createContext, useContext } from 'react';

export type UiCopyContextValue = {
  /**
   * Returns the CMS value for `key`, or `fallback` while the fetch is loading, on fetch
   * error, or when no `uiCopy` entry with that key exists yet. When `values` is passed,
   * every `{token}` in the resolved string (CMS value or fallback) is replaced from it —
   * mirrors react-intl's `formatMessage(descriptor, values)` shape closely enough that a
   * call site converting away from react-intl only has to change the function, not the
   * string template itself.
   */
  t: (key: string, fallback: string, values?: Record<string, string | number>) => string;
  isLoading: boolean;
};

/**
 * Replaces every `{token}` in `template` with `values[token]`, left untouched if `token`
 * isn't in `values`. Shared by both the real UiCopyProvider and FALLBACK_ONLY below so a
 * key with no matching Contentful entry still interpolates correctly against its fallback.
 */
export const interpolateUiCopy = (template: string, values?: Record<string, string | number>): string => {
  if (!values) return template;
  return template.replace(/\{(\w+)\}/g, (match, token: string) => (token in values ? String(values[token]) : match));
};

/**
 * Populated by UiCopyProvider (overrides/app/components/uiCopyProvider), mounted once in
 * _app-config. Not meant to be consumed directly — call useUiCopy() instead, which supplies
 * the no-Provider fallback.
 */
export const UiCopyContext = createContext<UiCopyContextValue | undefined>(undefined);

const FALLBACK_ONLY: UiCopyContextValue = {
  t: (_key: string, fallback: string, values?: Record<string, string | number>) => interpolateUiCopy(fallback, values),
  isLoading: false,
};

/**
 * App-wide UI-copy lookup, backed by Contentful's uiCopy content type — one entry per string,
 * fetched in a single bulk call by UiCopyProvider and shared via context, the same pattern
 * this app already uses for translations (`useIntl`) rather than the per-page container-fetch
 * pattern commerce-sdk-react hooks use. uiCopy is app-wide static content, not page-specific
 * business data, so it's safe to call from any component — including presentational leaves —
 * without threading it through as a prop.
 *
 * Safe to call with no UiCopyProvider mounted above it (Storybook, an isolated unit test):
 * degrades to fallback-only text instead of throwing, so every call site stays functional and
 * testable with zero setup.
 *
 * @returns `t` lookup function plus `isLoading`
 */
export const useUiCopy = (): UiCopyContextValue => useContext(UiCopyContext) ?? FALLBACK_ONLY;

/*
 * Copyright (c) 2021, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

import {useCallback, useContext} from 'react'
import {MultiSiteContext} from '@salesforce/retail-react-app/app/contexts'

/**
 * Custom React hook to get the function that returns usefule multi-site values, the site, the locale and
 * the function used to build URLs following the App configuration.
 * @returns {{site, locale, buildUrl: (function(*, *, *): *)}}
 */
const useMultiSite = () => {
    const context = useContext(MultiSiteContext)
    if (context === undefined) {
        throw new Error('useMultiSite must be used within MultiSiteProvider')
    }
    const {buildUrl: originalFn, site, locale} = context

    const buildUrl = useCallback(
        (path, siteRef, localeRef) => {
            return originalFn(
                path,
                siteRef ? siteRef : site?.alias || site?.id,
                localeRef ? localeRef : locale?.alias || locale?.id
            )
        },
        [originalFn, site, locale]
    )
    return {site, locale, buildUrl}
}

export default useMultiSite

{
  "compilerOptions": {
    // Type-checking only — Babel handles transpilation.
    "noEmit": true,

    // Path aliases — keep in sync with babel.config.js, vitest.config.ts, .storybook/main.js
    // (jest.config.js has its own separate alias entries for @salesforce/pwa-kit-dev's
    // internal tooling — see .docs/architecture.md — not part of this sync group)
    "paths": {
      "~/*": ["./*"],
      "app/*": ["./overrides/app/*"]
    },
    "isolatedModules": true,

    // Language
    "target": "ES2019",
    "lib": ["ES2019", "DOM"],
    "jsx": "react-jsx",

    // Modules
    "module": "ESNext",
    "moduleResolution": "bundler",
    "esModuleInterop": true,

    // Strictness
    "strict": true,

    // Skip type-checking of vendored .d.ts files in node_modules.
    "skipLibCheck": true
  },
  "include": ["overrides/**/*", "vitest.config.ts", "vitest.setup.ts"]
}

