import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { ZimmColourSwatch } from './index';

// Provide a minimal Chakra context so chakra() and useMultiStyleConfig resolve without
// needing the full Zimmermann theme (which would require the ZimmColourSwatch recipe
// to be registered before these tests are even loaded).
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return { ...actual, useMultiStyleConfig: () => ({ swatch: {}, image: {} }) };
});

const IMAGE = 'https://example.test/swatch.jpg';

const wrap = (ui: React.ReactElement) => render(<MemoryRouter>{ui}</MemoryRouter>);

describe('ZimmColourSwatch — link vs. span branch', () => {
  test('renders a router link (role radio) when href is provided', () => {
    wrap(
      <ZimmColourSwatch
        name="Ivory"
        imageUrl={IMAGE}
        href="/product/123?color=ivory"
        isSelected={false}
        isFocusable={true}
      />,
    );
    expect(screen.getByRole('radio', { name: 'Ivory' })).toBeInTheDocument();
  });

  test('renders a button with radio role when href is absent (linkless path)', () => {
    wrap(<ZimmColourSwatch name="Ivory" imageUrl={IMAGE} isSelected={false} isFocusable={false} />);
    const swatch = screen.getByRole('radio', { name: 'Ivory' });
    expect(swatch.tagName).toBe('BUTTON');
    expect(swatch).toHaveAttribute('aria-checked', 'false');
    expect(swatch).toHaveAttribute('tabindex', '-1');
  });

